// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }

    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint256).max / 2);
        // The contract holds `amount`; the Owner (this test contract, set as
        // Owner at deployment) calls withdraw(). C transfers its whole balance
        // out to the Owner, so c's balance must end at zero.
        vm.deal(address(c), amount);
        vm.prank(address(this));
        c.withdraw();
        assertTrue(address(c).balance == 0);
    }
}
